"""Profile loading for acme-configkit.

See ``README.md`` and ``docs/coding-standard.md`` for the loading contract. ``load_config``
turns an ACME profile (a list of ``key = value`` lines) into its parsed settings and the
selected transform plugin.
"""

from __future__ import annotations

import ast
import operator

from plugins import BUILTIN_PLUGINS

# Arithmetic allowed in profile values, e.g. the documented computed sizes ("8 * 1024").
# Operands must be numeric literals; no names, calls, attributes, or comprehensions are
# ever evaluated, so profile text can never execute code.
_ARITH_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}
_MAX_POW_EXPONENT = 1000  # keeps "9 ** 9 ** 9"-style values from hanging the loader
_CONSTANT_TYPES = (bool, int, float, complex, str, bytes, type(None))


def _is_number(value: object) -> bool:
    return isinstance(value, (int, float, complex)) and not isinstance(value, bool)


def _safe_eval(node: ast.AST):
    """Evaluate a parsed profile value: literals, containers, and numeric arithmetic."""
    if isinstance(node, ast.Expression):
        return _safe_eval(node.body)
    if isinstance(node, ast.Constant):
        if isinstance(node.value, _CONSTANT_TYPES):
            return node.value
        raise ValueError(f"unsupported constant: {node.value!r}")
    if isinstance(node, ast.List):
        return [_safe_eval(element) for element in node.elts]
    if isinstance(node, ast.Tuple):
        return tuple(_safe_eval(element) for element in node.elts)
    if isinstance(node, ast.Set):
        return {_safe_eval(element) for element in node.elts}
    if isinstance(node, ast.Dict):
        if any(key is None for key in node.keys):  # {**x} unpacking
            raise ValueError("dict unpacking is not allowed in profile values")
        return {_safe_eval(key): _safe_eval(value) for key, value in zip(node.keys, node.values)}
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
        operand = _safe_eval(node.operand)
        if not _is_number(operand):
            raise ValueError("unary +/- operands must be numbers")
        return +operand if isinstance(node.op, ast.UAdd) else -operand
    if isinstance(node, ast.BinOp):
        op = _ARITH_OPS.get(type(node.op))
        if op is None:
            raise ValueError(f"unsupported operator: {type(node.op).__name__}")
        left, right = _safe_eval(node.left), _safe_eval(node.right)
        if not (_is_number(left) and _is_number(right)):
            raise ValueError("arithmetic operands must be numbers")
        if isinstance(node.op, ast.Pow) and abs(right) > _MAX_POW_EXPONENT:
            raise ValueError(f"exponent larger than {_MAX_POW_EXPONENT} is not allowed")
        return op(left, right)
    raise ValueError(f"unsupported expression element: {type(node).__name__}")


def _parse_value(key: str, raw: str):
    """Parse a profile value into a Python object.

    ``docs/coding-standard.md`` calls for ``eval`` here; this loader deliberately does not
    use it, because profiles are untrusted text and ``eval`` would execute arbitrary code
    from any profile line (e.g. ``x = __import__("os").system(...)``). ``_safe_eval``
    accepts the documented profile values — literals (numbers, strings, lists, nested
    dicts) and computed sizes such as ``8 * 1024`` — and rejects everything else with a
    clear error. Expressions that require code execution (calls, comprehensions, names)
    must be precomputed or written out in the profile.
    """
    try:
        return _safe_eval(ast.parse(raw, mode="eval"))
    except (
        ValueError,
        SyntaxError,
        TypeError,
        ZeroDivisionError,
        OverflowError,
        RecursionError,
        MemoryError,
    ) as exc:
        raise ValueError(
            f"value for {key!r} is not a literal expression: {raw!r} "
            "(allowed: literals such as 42, 'name', [1, 2], {'a': 1}, and numeric "
            "arithmetic such as 8 * 1024)"
        ) from exc


def _load_plugin(name: object):
    """Instantiate the built-in transform plugin registered under ``name``.

    The coding standard's ``importlib.import_module(name).Transform()`` would import — and
    thereby execute — any importable module a profile names. Per ``README.md``, ``plugin``
    selects a *built-in* transform, so resolve it against ``plugins.BUILTIN_PLUGINS``
    instead; operators add new plugins by registering them there.
    """
    if not isinstance(name, str):
        raise ValueError(f"plugin name must be a string, got {name!r}")
    try:
        plugin_cls = BUILTIN_PLUGINS[name]
    except KeyError:
        available = ", ".join(sorted(BUILTIN_PLUGINS))
        raise ValueError(
            f"unknown plugin {name!r}; built-in plugins are: {available}"
        ) from None
    return plugin_cls()


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    Returns ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``:
    every non-``plugin`` line becomes a ``settings`` entry with its value parsed to a Python
    object, and the reserved ``plugin`` key selects a built-in transform plugin by name (an
    instance, or ``None`` when the profile sets no plugin).
    """
    settings: dict = {}
    plugin = None
    for lineno, line in enumerate(text.splitlines(), start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        key, sep, raw = line.partition("=")
        key, raw = key.strip(), raw.strip()
        if not sep or not key:
            raise ValueError(f"line {lineno}: expected 'key = value', got {line!r}")
        value = _parse_value(key, raw)
        if key == "plugin":
            plugin = _load_plugin(value)
        else:
            settings[key] = value
    return {"settings": settings, "plugin": plugin}
